package ru.zhivo.app.core

import org.junit.Assert.*
import org.junit.Test
import ru.zhivo.app.data.CourseCodec
import ru.zhivo.app.data.StateCodec
import java.io.File
import java.time.Instant
import java.time.LocalDate
import java.time.ZoneId

class LearningTest {
    private fun task(answer:String="Я читаю книгу.",strict:Boolean=false)=Task("a1_test_1",TaskType.FILL,"Заполните",listOf(answer),explanation="Объяснение",strictYo=strict)
    private fun course():Course=CourseCodec.decode(File("src/main/assets/course.json").readText())
    @Test fun spacingCasePunctuationAndStress(){assertTrue(AnswerChecker.matches(task(),"  я   чита́ю КНИГУ! "));assertTrue(AnswerChecker.matches(task("Ёж"),"еж"))}
    @Test fun meaningfulYoRemainsDistinct(){assertFalse(AnswerChecker.matches(task("всё",true),"все"));assertTrue(AnswerChecker.matches(task("всё",true),"ВСЁ"))}
    @Test fun shortIIsNotI(){assertFalse(AnswerChecker.matches(task("мой"),"мои"));assertTrue(AnswerChecker.matches(task("мой"),"мои\u0306"))}
    @Test fun grammaticalAndExtraWordsAreRejected(){assertFalse(AnswerChecker.matches(task(),"Я читать книгу"));assertFalse(AnswerChecker.matches(task(),"Я не читаю книгу"));assertFalse(AnswerChecker.matches(task(),"Он говорит я читаю книгу"))}
    @Test fun allowedAlternativeOrderIsExplicit(){val t=task().copy(answers=listOf("Я читаю книгу.","Книгу я читаю."));assertTrue(AnswerChecker.matches(t,"Книгу я читаю"));assertFalse(AnswerChecker.matches(t,"Читаешь я книгу"))}
    @Test fun matchingIsExactOneToOne(){val t=task().copy(type=TaskType.MATCH,answers=emptyList(),pairs=listOf("дом" to "здание","кот" to "животное","мама" to "мать"));assertTrue(AnswerChecker.matches(t,"дом\tздание\nкот\tживотное\nмама\tмать"));assertFalse(AnswerChecker.matches(t,"дом\tздание\nкот\tживотное\nмама\tмать\nкот\tмать"))}
    @Test fun correctIntervalsIncrease(){val now=1_000_000L;val first=ReviewScheduler.rate(ReviewCard(),4,now);val second=ReviewScheduler.rate(first,4,first.due);val third=ReviewScheduler.rate(second,5,second.due);assertEquals(1,first.intervalDays);assertEquals(3,second.intervalDays);assertTrue(third.intervalDays>3);assertTrue(second.verifiedAt>0)}
    @Test fun failedCardReturnsInTenMinutes(){val c=ReviewScheduler.rate(ReviewCard(intervalDays=30,repetitions=4,ease=2.5),1,1000);assertEquals(601000,c.due);assertEquals(0,c.repetitions);assertEquals(1,c.lapses);assertEquals(0,c.verifiedAt)}
    @Test fun easeBoundsAndAnnualCap(){var c=ReviewCard(intervalDays=360,repetitions=5);repeat(200){c=ReviewScheduler.rate(c,5,1_000_000L+it*ReviewScheduler.DAY)};assertEquals(365,c.intervalDays);assertEquals(3.0,c.ease,0.001);repeat(100){c=ReviewScheduler.rate(c,0,1_000_000L)};assertEquals(1.3,c.ease,0.001)}
    @Test fun aLapseRemovesEarlierVerification(){val c=ReviewScheduler.rate(ReviewCard(introducedAt=1000,verifiedAt=2000,repetitions=3),1,3_000_000);assertEquals(0,c.verifiedAt)}
    @Test fun goalPrioritizesThemesAfterFoundations(){val c=course();val lessons=c.lessons.filter{it.stage=="a1"};val done=lessons.take(8).associate{it.id to LessonProgress(completedAt=1000)};val travel=Learning.recommend(c,StudyState(profile=Profile(goal="Путешествия",startStage="a1"),progress=done));assertEquals("Транспорт",travel!!.topic);assertEquals(lessons.first().id,Learning.recommend(c,StudyState(profile=Profile(goal="Путешествия",startStage="a1")))!!.id)}
    @Test fun selfRatingDoesNotVerify(){val c=ReviewScheduler.rate(ReviewCard(introducedAt=1000),5,1000+ReviewScheduler.DAY,false);assertEquals(0,c.verifiedAt)}
    @Test fun earlyAnswerDoesNotVerify(){val c=ReviewScheduler.rate(ReviewCard(introducedAt=1000),5,2000);assertEquals(0,c.verifiedAt)}
    @Test fun wrongThenCorrectIsNotFirstTry(){val t=task();val s=Session("a1_test").respond(t,"неверно").respond(t,"Я читаю книгу");assertEquals(2,s.answers[t.id]?.attempts);assertEquals(false,s.answers[t.id]?.firstCorrect);assertEquals(true,s.answers[t.id]?.solved)}
    @Test fun revealedAnswerDoesNotCountAsIndependent(){val t=task();val a=Session("x").respond(t,"",reveal=true).answers.getValue(t.id);assertTrue(a.revealed);assertTrue(a.solved);assertFalse(a.firstCorrect)}
    @Test fun skippedAnswerIsUnassessed(){val t=task();val a=Session("x").respond(t,"",skip=true).answers.getValue(t.id);assertTrue(a.unassessed);assertFalse(a.firstCorrect);assertFalse(a.solved)}
    @Test fun solvedAnswerCannotBeScoredTwice(){val t=task();val s=Session("x").respond(t,"Я читаю книгу");assertEquals(s,s.respond(t,"потом ошибка"))}
    @Test fun finishIsIdempotentAndIncompleteCannotFinish(){val c=course();val l=c.lessons.first();var s=StudyState(session=Session(l.id,startedAt=1000));assertEquals(s,Learning.finish(s,l,2000));for(t in l.tasks)s=s.copy(session=s.session!!.respond(t,if(t.type==TaskType.MATCH)t.pairs.joinToString("\n"){"${it.first}\t${it.second}"} else t.answers.firstOrNull().orEmpty(),skip=t.type==TaskType.SPEAK));val done=Learning.finish(s,l,3000);assertTrue(done.session!!.finished);assertEquals(done,Learning.finish(done,l,4000));assertEquals(8,done.progress[l.id]!!.bestCorrect);assertTrue(done.reviews.isNotEmpty())}
    @Test fun transcriptDoesNotCountWhenSkipped(){val t=task().copy(type=TaskType.DICTATION);val failed=Session("x").respond(t,"неверно",transcript=true);assertFalse(failed.answers.getValue(t.id).solved);assertFalse(failed.answers.getValue(t.id).unassessed);val a=failed.respond(t,"Я читаю книгу",transcript=true).answers.getValue(t.id);assertTrue(a.transcript);assertTrue(a.unassessed);assertFalse(a.firstCorrect)}
    @Test fun reviewedStatusRequiresElapsedDay(){val now=1_000_000L;val card=ReviewCard(introducedAt=now);assertEquals(0,ReviewScheduler.rate(card,4,now+ReviewScheduler.DAY-1).verifiedAt);assertEquals(now+ReviewScheduler.DAY,ReviewScheduler.rate(card,4,now+ReviewScheduler.DAY).verifiedAt)}
    @Test fun recommendationResumesAndRespectsStart(){val c=course();val s=StudyState(profile=Profile(startStage="a2"));assertEquals("a2",Learning.recommend(c,s)!!.stage);val l=c.lessons.first();assertEquals(l.id,Learning.recommend(c,s.copy(session=Session(l.id)))!!.id)}
    @Test fun timestampsRespectLocalTimezone(){val at=Instant.parse("2026-01-01T22:30:00Z").toEpochMilli();assertEquals(LocalDate.of(2026,1,2),Learning.day(at,ZoneId.of("Asia/Dushanbe")));assertEquals(LocalDate.of(2026,1,1),Learning.day(at,ZoneId.of("America/New_York")))}
    @Test fun reminderHandlesDaylightSavingAndNextDay(){val now=Instant.parse("2026-03-28T23:00:00Z").toEpochMilli();val target=Learning.nextReminder(now,ZoneId.of("Europe/Berlin"),2,30);assertTrue(target>now);val next=Learning.nextReminder(target,ZoneId.of("Europe/Berlin"),2,30);assertTrue(next>target);assertTrue(next-target in 22*3_600_000L..26*3_600_000L)}
    @Test fun diagnosticIsLimitedOrientation(){assertEquals("a1",Learning.diagnostic(emptyMap()));assertEquals("a2",Learning.diagnostic(mapOf("a1" to (3 to 4))));assertEquals("b2",Learning.diagnostic(mapOf("a1" to (4 to 4),"a2" to (4 to 4),"b1" to (3 to 4))))}
    @Test fun fullStateRoundTripsIncludingInterruptedWrongAnswer(){val c=course();val l=c.lessons.first();val t=l.tasks.first();val s=StudyState(profile=Profile(onboarded=true,theme="dark"),session=Session(l.id,index=2,answers=mapOf(t.id to Answer(2,false,false,draft="ответ"))),progress=mapOf(l.id to LessonProgress(1000,2000,4,8)),reviews=mapOf(l.words.first() to ReviewCard(4000,1,1,2.5,1,1000)),favorites=setOf(l.words.first()),errors=mapOf(t.id to 2),customWords=listOf(CustomWord("custom_test","слово","значение","пример")),events=listOf(StudyEvent("e",1000,10000,"lesson")),dialogueWins=setOf(c.dialogues.first().id),dialogueNodes=mapOf(c.dialogues.first().id to "detail"));assertEquals(s,StateCodec.decode(StateCodec.encode(s),c))}
    @Test fun versionOneMigratesWithoutLosingProgress(){val c=course();val id=c.lessons.first().id;val s=StudyState(progress=mapOf(id to LessonProgress(100,200,2,8)));val text=StateCodec.encode(s).replace("\"version\":2","\"version\":1");val restored=StateCodec.decode(text,c);assertEquals(2,restored.version);assertEquals(s.progress,restored.progress)}
    @Test fun unsafeImportsAreRejected(){val c=course();val valid=StateCodec.encode(StudyState());for(text in listOf(valid.replace("\"version\":2","\"version\":999"),valid.replace("\"dailyMinutes\":10","\"dailyMinutes\":-1"),valid.replace("zhivo-backup","other"),"{}","x".repeat(32_000_001))){assertTrue(runCatching{StateCodec.decode(text,c)}.isFailure)}}
    @Test fun courseContainsActualAllStageContent(){val c=course();assertEquals(emptyList<String>(),c.errors());assertEquals(mapOf("start" to 8,"a1" to 18,"a2" to 18,"b1" to 16,"b2" to 12),c.lessons.groupingBy{it.stage}.eachCount());assertEquals(648,c.tasksById.size);assertEquals(216,c.words.size);assertEquals(14,c.dialogues.size);assertEquals(TaskType.entries.toSet(),c.tasksById.values.map{it.type}.toSet())}
    @Test fun allCanonicalAnswersAcceptedAndAlternativesNotBlank(){val c=course();for(t in c.tasksById.values.filter{it.graded&&it.type!=TaskType.MATCH}){assertTrue(t.id,AnswerChecker.matches(t,t.answers.first()));assertTrue(t.id,t.answers.none{it.isBlank()});assertTrue(t.id,t.answers.none{AnswerChecker.matches(t,"НЕПРАВИЛЬНЫЙ ответ посторонний текст")})}}
    @Test fun dialoguesHaveReachableSuccessAndRecovery(){val c=course();for(d in c.dialogues){val reachable=mutableSetOf("start");repeat(d.nodes.size){d.nodes.filter{it.id in reachable}.flatMap{it.replies}.forEach{reachable.add(it.next)}};assertTrue(d.id,d.nodes.filter{it.id in reachable}.flatMap{it.replies}.any{it.next=="end"&&it.success});assertTrue(d.id,d.nodes.any{it.id=="repair"});assertTrue(d.id,d.nodes.all{it.replies.isNotEmpty()&&it.replies.all{r->r.feedback.isNotBlank()}})}}
}
